    dict(name='NidoWork', slug='nidowork', tagline='Tu lugar para hacer que pase.', idea='Cálido y cercano; el espacio se siente propio, cómodo y privado.', primary='#16A675', secondary='#EAF7F0', ink='#103F37', mark='<rect x="10" y="10" width="72" height="72" rx="24" fill="{p}"/><path d="M25 49l21-18 21 18v21H25z" fill="none" stroke="white" stroke-width="6" stroke-linejoin="round"/><path d="M36 70V50l10 10 10-10v20" fill="none" stroke="white" stroke-width="5" stroke-linejoin="round"/>', rank='Cálido'),
