for i, b in enumerate(brands, 1):
    mark = b['mark'].format(p=b['primary'], s=b['secondary'])
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="620" height="130" viewBox="0 0 620 130" role="img" aria-label="Logotipo {escape(b['name'])}">
<rect width="620" height="130" rx="22" fill="white"/>
<g transform="translate(16 18)">{mark}</g>
<text x="123" y="75" font-family="Arial, Helvetica, sans-serif" font-size="45" font-weight="800" letter-spacing="-1.5" fill="{b['ink']}">{escape(b['name'])}</text>
<text x="125" y="99" font-family="Arial, Helvetica, sans-serif" font-size="12" font-weight="700" letter-spacing="2.8" fill="{b['primary']}">DELICIAS · CHIHUAHUA</text>
</svg>'''
    (OUT / f'{i:02d}-{b["slug"]}.svg').write_text(svg, encoding='utf-8')

cards = []
for i, b in enumerate(brands, 1):
    cards.append(f'''<article class="card"><div class="number">{i:02d} <span>{escape(b['rank'])}</span></div><div class="logo"><img src="{i:02d}-{b['slug']}.svg" alt="Logotipo de {escape(b['name'])}"></div><div class="body"><h2>{escape(b['name'])}</h2><p class="tagline">{escape(b['tagline'])}</p><p class="idea">{escape(b['idea'])}</p><div class="colors"><span style="background:{b['primary']}"></span><span style="background:{b['secondary']}"></span><span style="background:{b['ink']}"></span><code>{b['primary']} · {b['secondary']} · {b['ink']}</code></div></div></article>''')

html = '''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>10 nombres y logos · Espacios de trabajo Delicias</title><style>
*{box-sizing:border-box}body{margin:0;background:#F4F6F3;color:#1B2927;font-family:Arial,Helvetica,sans-serif}header{padding:52px max(24px,calc((100vw - 1180px)/2));background:#103F37;color:white}header .eyebrow{color:#83E2B5;font-size:12px;font-weight:800;letter-spacing:2px}h1{font-size:clamp(32px,5vw,55px);letter-spacing:-2px;line-height:1.05;margin:16px 0}header p{color:#CDE6DB;max-width:650px;line-height:1.6}main{max-width:1180px;margin:0 auto;padding:34px 20px 70px}.intro{font-size:14px;color:#667771;line-height:1.6;margin:0 0 28px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:#fff;border:1px solid #E2E9E4;border-radius:22px;overflow:hidden;box-shadow:0 6px 22px #102e2410}.number{display:flex;justify-content:space-between;padding:15px 20px;color:#81908A;font-size:12px;font-weight:800;letter-spacing:2px}.number span{letter-spacing:0;color:#668077}.logo{margin:0 18px;background:#F6F8F5;border-radius:15px;padding:10px}.logo img{display:block;width:100%;height:auto}.body{padding:20px}.body h2{font-size:22px;margin:0 0 6px}.tagline{font-size:14px;font-weight:800;margin:0;color:#1D5849}.idea{font-size:13px;color:#667771;line-height:1.5;min-height:39px}.colors{display:flex;align-items:center;gap:7px;margin-top:18px}.colors span{height:24px;width:24px;border-radius:50%;border:1px solid #0001}.colors code{font-size:11px;color:#6C7873;margin-left:6px;white-space:nowrap}.foot{background:#E7EFE9;padding:22px;border-radius:16px;color:#426157;font-size:13px;line-height:1.6;margin-top:28px}@media(max-width:760px){.grid{grid-template-columns:1fr}header{padding:42px 22px}.colors code{font-size:10px}}
</style></head><body><header><div class="eyebrow">IDENTIDAD DE MARCA · DELICIAS, CHIHUAHUA</div><h1>Un lugar listo<br>para trabajar.</h1><p>Diez rutas de nombre, logotipo y color para una plataforma que permite descubrir y reservar oficinas, salas y espacios de coworking por horas, días o semanas.</p></header><main><p class="intro">Los símbolos son bocetos vectoriales originales para comparar direcciones de marca. Cada propuesta incluye su paleta y una promesa de servicio.</p><div class="grid">''' + ''.join(cards) + '''</div><div class="foot">Antes de elegir un nombre para uso comercial, comprueba disponibilidad de marca ante el IMPI, dominio web y redes sociales. Las propuestas todavía no constituyen una identidad final registrada.</div></main></body></html>'''
(OUT / 'comparativo.html').write_text(html, encoding='utf-8')
